package cl.zkage.verifier

import java.io.File
import org.junit.Assert.assertEquals
import org.junit.Test

class ChileCscaTest {
    /**
     * The Rust verifier's list, generated by `gen_csca.py --rust` with its own DER encoder,
     * carries the same SPKI hashes Bouncy Castle computes, in the same order.
     */
    @Test
    fun rustListMatches() {
        val rust = File("../../prover/verifier/src/chile_csca.rs").readText()
        val rows = Regex("""\("([^"]+)", \[([^\]]+)\]\)""").findAll(rust).map { m ->
            m.groupValues[1] to m.groupValues[2].split(",").joinToString("") { it.trim().removePrefix("0x") }
        }.toList()
        val kotlin = ChileCsca.keys.map { it.label to it.spkiSha256().joinToString("") { b -> "%02x".format(b) } }
        assertEquals(kotlin, rows)
    }
}
